class Router:
    def __init__(self):
        self.routes = {
            '/': 'home',
            '/health': 'ok',
        }

    def resolve(self, path):
        return self.routes.get(path, None)

    def paths_for(self, target):
        return sorted([path for path, route_target in self.routes.items() if route_target == target])
